pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint128 amount1, uint128 amount2, address caller) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(caller != address(0) && caller != address(c));
        vm.deal(caller, uint256(amount1) + uint256(amount2));
        vm.deal(address(c), uint256(amount1) + uint256(amount2));

        vm.prank(caller);
        c.addToBalance{value: amount1}();

        vm.prank(caller);
        c.withdrawBalance();

        vm.prank(caller);
        c.addToBalance{value: amount2}();

        bool ok;
        uint256 balanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        assertEq(c.getBalance(caller), 0);
    }
}
